CREATE DATABASE IF NOT EXISTS artcare_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE artcare_db;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','staff') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, contact VARCHAR(40), email VARCHAR(120), address TEXT, birth_date DATE NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL, appointment_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, service VARCHAR(120) NOT NULL, status ENUM('Pending','Confirmed','Rescheduled','Completed','Cancelled','No-Show') NOT NULL DEFAULT 'Pending', notes TEXT, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE RESTRICT, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_schedule (appointment_date,start_time,end_time));
CREATE TABLE IF NOT EXISTS appointment_history (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, changed_by INT NULL, changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (appointment_id) REFERENCES appointments(id) ON DELETE CASCADE, FOREIGN KEY (changed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS clinic_settings (id TINYINT PRIMARY KEY, clinic_name VARCHAR(150) NOT NULL, contact VARCHAR(40), address TEXT, opening_time TIME NOT NULL, closing_time TIME NOT NULL, duration_minutes INT NOT NULL DEFAULT 30);
